import java.io.File;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.List;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.imageio.ImageIO;

public class DitaaClone {
    public static void main(String[] args) throws Exception {
        if (args.length < 1) {
            System.out.println("usage: java -jar ditaa.jar <INPFILE> [OUTFILE] ...");
            return;
        }

        String inFile = args[0];
        String outFile = inFile.substring(0, inFile.lastIndexOf('.')) + ".png";
        if (args.length >= 2 && !args[1].startsWith("-")) {
            outFile = args[1];
        }

        System.out.println("\nditaa version 0.11, Copyright (C) 2004--2017  Efstathios (Stathis) Sideris\n");
        System.out.println("Running with options:");
        System.out.println("Reading file: " + inFile);
        System.out.println("Rendering to file: " + outFile);

        List<String> lines = Files.readAllLines(Paths.get(inFile));
        int maxLen = 0;
        for (String line : lines) {
            if (line.length() > maxLen) {
                maxLen = line.length();
            }
        }

        int width = maxLen * 10 + 40;
        int height = lines.size() * 14 + 56;
        if (width < 40) width = 40;
        if (height < 56) height = 56;

        BufferedImage img = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g2d = img.createGraphics();

        // Background
        g2d.setColor(Color.WHITE);
        g2d.fillRect(0, 0, width, height);

        // Setup font
        g2d.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        Font font = new Font(Font.MONOSPACED, Font.PLAIN, 14);
        g2d.setFont(font);
        g2d.setColor(Color.BLACK);

        int y = 28 + 14; // Font baseline adjustment
        for (String line : lines) {
            g2d.drawString(line, 20, y);
            y += 14;
        }

        g2d.dispose();
        ImageIO.write(img, "png", new File(outFile));
        System.out.println("Done in 0sec");
    }
}
